// ../source/src/shared/modules/production/blueprints/firearm-weapon.blueprints.ts
init_define_process();
var FirearmWeaponBlueprint = makeKeys()(FirearmWeapon);
Object.values(FirearmWeaponBlueprint).forEach((key) => {
  const itemKey = key;
  const tier = getItemTier(itemKey);
  const multiplier = tier !== null ? {
    ["S" /* S */]: 10,
    ["A" /* A */]: 8,
    ["B" /* B */]: 6,
    ["C" /* C */]: 4,
    ["D" /* D */]: 3,
    ["E" /* E */]: 2,
    ["F" /* F */]: 1
  }[tier] : 1;
  registerBlueprint({
    key,
    name: `${getItemName(itemKey)} blueprint`,
    description: `Lets you craft and upgrade ${getItemName(itemKey)}.`,
    recipes: [
      // base
      {
        key: itemKey,
        durationSeconds: 2,
        item: {
          key: itemKey,
          grade: "common" /* COMMON */
        },
        parts: [
          { key: Metal.METAL, grade: "common" /* COMMON */, amount: 5 * multiplier },
          { key: Scrap.SCRAP, grade: "common" /* COMMON */, amount: 5 * multiplier }
        ]
      },
      // +1
      {
        key: itemKey + "+1",
        isUpgrade: true,
        durationSeconds: 5,
        item: {
          key: itemKey,
          grade: "uncommon" /* UNCOMMON */
        },
        parts: [
          { key: itemKey, grade: "common" /* COMMON */ },
          { key: Metal.METAL, grade: "uncommon" /* UNCOMMON */, amount: 10 * multiplier },
          { key: Scrap.SCRAP, grade: "uncommon" /* UNCOMMON */, amount: 10 * multiplier }
        ]
      },
      // +2
      {
        key: itemKey + "+2",
        isUpgrade: true,
        durationSeconds: 10,
        item: {
          key: itemKey,
          grade: "rare" /* RARE */
        },
        parts: [
          { key: itemKey, grade: "uncommon" /* UNCOMMON */ },
          { key: Metal.METAL, grade: "rare" /* RARE */, amount: 15 * multiplier },
          { key: Scrap.SCRAP, grade: "rare" /* RARE */, amount: 15 * multiplier }
        ]
      },
      // +3
      {
        key: itemKey + "+3",
        isUpgrade: true,
        durationSeconds: 20,
        item: {
          key: itemKey,
          grade: "epic" /* EPIC */
        },
        parts: [
          { key: itemKey, grade: "rare" /* RARE */ },
          { key: Metal.METAL, grade: "epic" /* EPIC */, amount: 20 * multiplier },
          { key: Scrap.SCRAP, grade: "epic" /* EPIC */, amount: 20 * multiplier }
        ]
      },
      // +4
      {
        key: itemKey + "+4",
        isUpgrade: true,
        durationSeconds: 30,
        item: {
          key: itemKey,
          grade: "legendary" /* LEGENDARY */
        },
        parts: [
          { key: itemKey, grade: "epic" /* EPIC */ },
          { key: Metal.METAL, grade: "legendary" /* LEGENDARY */, amount: 25 * multiplier },
          { key: Scrap.SCRAP, grade: "legendary" /* LEGENDARY */, amount: 25 * multiplier }
        ]
      }
    ]
  });
});

