// ../source/src/shared/modules/production/blueprints/tool.blueprints.ts
var ToolBlueprint = makeKeys()({
  ...FishingRod,
  ...Hatchet,
  ...Pickaxe
});
Object.values(ToolBlueprint).forEach((key) => {
  const itemKey = key;
  registerBlueprint({
    key,
    name: `${getItemName(itemKey)} blueprint`,
    description: `Lets you craft and upgrade ${getItemName(itemKey)}.`,
    recipes: [
      {
        key: itemKey,
        durationSeconds: 3,
        item: {
          key: itemKey,
          grade: "common" /* COMMON */
        },
        parts: [
          { key: Wood.WOOD, grade: "common" /* COMMON */, amount: 5 },
          { key: Metal.METAL, grade: "common" /* COMMON */, amount: 5 }
        ]
      },
      {
        key: itemKey + "+1",
        isUpgrade: true,
        durationSeconds: 5,
        item: {
          key: itemKey,
          grade: "uncommon" /* UNCOMMON */
        },
        parts: [
          { key: itemKey, grade: "common" /* COMMON */ },
          { key: Wood.WOOD, grade: "uncommon" /* UNCOMMON */, amount: 5 },
          { key: Metal.METAL, grade: "uncommon" /* UNCOMMON */, amount: 5 }
        ]
      },
      {
        key: itemKey + "+2",
        isUpgrade: true,
        durationSeconds: 10,
        item: {
          key: itemKey,
          grade: "rare" /* RARE */
        },
        parts: [
          { key: itemKey, grade: "uncommon" /* UNCOMMON */ },
          { key: Wood.WOOD, grade: "rare" /* RARE */, amount: 5 },
          { key: Metal.METAL, grade: "rare" /* RARE */, amount: 5 }
        ]
      },
      {
        key: itemKey + "+3",
        isUpgrade: true,
        durationSeconds: 15,
        item: {
          key: itemKey,
          grade: "epic" /* EPIC */
        },
        parts: [
          { key: itemKey, grade: "rare" /* RARE */ },
          { key: Wood.WOOD, grade: "epic" /* EPIC */, amount: 5 },
          { key: Metal.METAL, grade: "epic" /* EPIC */, amount: 5 }
        ]
      },
      {
        key: itemKey + "+4",
        isUpgrade: true,
        durationSeconds: 20,
        item: {
          key: itemKey,
          grade: "legendary" /* LEGENDARY */
        },
        parts: [
          { key: itemKey, grade: "epic" /* EPIC */ },
          { key: Wood.WOOD, grade: "legendary" /* LEGENDARY */, amount: 5 },
          { key: Metal.METAL, grade: "legendary" /* LEGENDARY */, amount: 5 }
        ]
      }
    ]
  });
});

