init_define_process();
import alt58 from "@altv/client";
import game27 from "@altv/natives";
alt58.Events.onGameEntityCreate(({ entity }) => {
  if (!(entity instanceof alt58.Ped)) {
    return;
  }
  alt58.log("Ped created", entity.id);
  entity.cleanupFns = [];
  const key = entity.streamSyncedMeta.key;
  if (!key) {
    alt58.log("Ped has no key");
    return;
  }
  alt58.log("Registering interactions for ped", key);
  entity.interactions = (0, vue_exports.computed)(
    () => getPedInteractions(key).map((registration) => registration(entity)).flat()
  );
  entity.cleanupFns.push(() => {
    entity.interactions?.effect.stop();
  });
  const stopBlipWatch = (0, vue_exports.watch)([entity.interactions, clientState], ([interactions]) => {
    if (!interactions.length) {
      if (entity.blip) {
        game27.removeBlip(entity.blip);
        entity.blip = void 0;
      }
    } else {
      if (!entity.blip) {
        entity.blip = game27.addBlipForEntity(entity);
        game27.setBlipSprite(entity.blip, 456);
      }
      const trackingSameQuest = interactions.some(
        (interaction) => interaction.key === clientState.trackingQuest
      );
      if (trackingSameQuest) {
        game27.setBlipColour(entity.blip, alt58.Enums.BlipColor.YELLOW_ORANGE);
      } else {
        game27.setBlipColour(entity.blip, alt58.Enums.BlipColor.WHITE);
      }
    }
  });
  entity.cleanupFns.push(() => {
    stopBlipWatch();
    if (entity.blip) {
      game27.removeBlip(entity.blip);
    }
  });
});
alt58.Events.onGameEntityDestroy(({ entity }) => {
  if (!(entity instanceof alt58.Ped)) {
    return;
  }
  entity.cleanupFns.forEach((fn) => fn());
});

// ../source/src/client/modules/questing/quest-tracking.ts
init_define_process();
var cleanupPreviousTracking;
useWebview((webview2) => {
  webview2.on(ClientEvents.FromWebview.TRACK_QUEST, (questFact) => {
    const questTask = getQuestTask(questFact);
    if (!questTask) {
      return;
    }
    if (cleanupPreviousTracking) {
      cleanupPreviousTracking();
    }
    cleanupPreviousTracking = questTask.track?.();
    clientState.trackingQuest = questFact;
  });
});

